/** Lichen Agent artwork shared by the workbench entry and heading. */
import css from './EnterpriseBrand.module.css'

/**
 * Render the supplied Lichen Agent mark and optional localized name.
 * @param props.label - Name supplied by the owning locale; omitted on a compact rail.
 * @param props.heading - Use the larger workbench heading presentation.
 * @returns The reference logo and Tourney lettering.
 */
export function EnterpriseBrand({ label, heading = false }: { label?: string; heading?: boolean }) {
  return <span className={heading ? css.heading : css.brand}>
    <span className={css.mark} aria-hidden="true">
      <img src="data:image/svg+xml;base64," alt="" />
      <img src="data:image/svg+xml;base64," alt="" />
    </span>
    {label !== undefined && <span className={css.name}>{label}</span>}
  </span>
}
